mapper.sql:
WHERE (#{scope.admin}=TRUE OR o.operator_id=#{scope.userId})
  AND (o.order_no LIKE CONCAT('%',#{q.keyword},'%') OR EXISTS(SELECT 1 FROM stocktake_item si JOIN purchase_item pi ON pi.id=si.batch_item_id WHERE si.stocktake_id=o.id AND (pi.product_name LIKE CONCAT('%',#{q.keyword},'%') OR pi.product_code LIKE CONCAT('%',#{q.keyword},'%'))))
  AND o.status=#{q.status}
  AND o.started_at>=#{q.startDate}
  AND o.started_at<DATE_ADD(#{q.endDate},INTERVAL 1 DAY)
